function armReworkLatch(ticket) {
    if (DRY) return;
    var prNumber = ticket && ticket.prNumber;
    var head = reworkLatchHeadOf(ticket);
    if (!prNumber || !head) return;
    var latchState = tickReworkLatchState(null);
