        var ms = rc.parseRestoreMarkers(
            [{ body: body, user: { login: 'ai-teammate' } }],
            { authorLogins: ['ai-teammate'] });
        assert.equal(ms.length, 1);
        assert.equal(ms[0].head, 'abc1234');
    });
});

