        asList(parseMcp(github_list_prs({
            workspace: repoInfo.owner, repository: repoInfo.repo, state: 'open'
        })));

    var items = prs.map(function (p) {
        return {
            key: 'pr-' + p.number,
            labels: prLabels(p),
            pr: null,
            issueNumber: linkedIssueNumber(p.body),
            prNumber: p.number,
            draft: !!p.draft,
