function reworkLatchHeadOf(ticket) {
    return (ticket && ticket.pr && ticket.pr.headSha) ||
        (ticket && ticket.headSha) || null;
}

/**
 * The AC1 gate — is a rework leg already in flight for (ticket.prNumber,
 * head)? Returns { latched, head }; the caller must arm/dispatch NOTHING
 * when latched. The canonical suppression line
 * `⏭️ <key> rework already in flight for (pr-N, head7)` is logged HERE,
 * exactly once per suppressed decision.
 * Side effects on a PRESENT latch: one head-runs probe decides its fate —
 * an ACTIVE leg run keeps it alive past the stale window (the leg really
 * is flying), a CONCLUDED leg run at/after the arm clears it (AC2), no run
 * + older than 45 min self-heals (AC3). A null probe (failed gh call)
 * degrades to age-only — fail-safe toward suppressing one extra arm,
 * never toward stacking legs. The clear is logged with its cause.
 */
function consultReworkLatch(key, ticket, effectiveRepoInfo) {
    var prNumber = ticket && ticket.prNumber;
    var head = reworkLatchHeadOf(ticket);
    if (!prNumber || !head) return { latched: false, head: head };
    var latchState = tickReworkLatchState(effectiveRepoInfo);
    var verdict = reworkLatchModule.isActive(latchState.map, prNumber, head, {});
    if (verdict.entry) {
        var runs = headWorkflowRunsSafe(effectiveRepoInfo, head);
        verdict = reworkLatchModule.isActive(latchState.map, prNumber, head, {
            runs: runs,
            workflowFile: reworkLatchModule.DEFAULT_LEG_WORKFLOW
        });
    }
    if (!verdict.active) {
        if (verdict.entry) {
            reworkLatchModule.clear(latchState.map, prNumber, head);
            console.log('  🔓 ' + key + ' rework latch cleared (' + verdict.cause +
                ') for (pr-' + prNumber + ', ' + head.substring(0, 7) + ')');
        }
        return { latched: false, head: head };
    }
    console.log('  ⏭️  ' + key + ' rework already in flight for (pr-' + prNumber +
        ', ' + head.substring(0, 7) + ')');
    return { latched: true, head: head };
}

/**
 * Record an arming decision (gh-806): from now on, one leg for (pr, head).
 * DRY never arms (the dry tick publishes nothing — arming a map that never
 * persists would silently swallow the NEXT real tick's first arm).
 */
function armReworkLatch(ticket) {
    if (DRY) return;
    var prNumber = ticket && ticket.prNumber;
    var head = reworkLatchHeadOf(ticket);
    if (!prNumber || !head) return;
    var latchState = tickReworkLatchState(null);
    reworkLatchModule.arm(latchState.map, prNumber, head, null, 'sm');
}

function action(params) {
    var p     = params.jobParams || params;
    RUN_JOB_PARAMS = p;    DRY = p.dryRun === true;
    tickReworkLatch = null;
    if (DRY) console.log('🧪 DRY RUN — no side effects will be performed');
    var rules = p.rules;

    // Load global project configuration (used as default when rules have no configPath)
    projectConfig = configLoader.loadProjectConfig(p);

    var configuredWorkflowCap = resolveWorkflowCap(
        typeof p.maxTriggeredWorkflows !== 'undefined' ? p.maxTriggeredWorkflows : p.maxWorkflowsPerRun,
        projectConfig
                 '/actions/runs?head_sha=' + headSha + '&per_page=50"'
    });
    var runs = mcpParse((res || {}).output || (res || {}).stdout || res);
    return (runs && runs.workflow_runs) || [];
}

function headWorkflowRunsSafe(repoInfo, headSha) {
    // headWorkflowRuns + fail-OPEN wrapper: a probe error must not kill
    // the action (worst case: one rerun too many — the same worst case
    // the dispatch guard accepts). null = the probe failed; callers that
    // still need the rollup refetch it themselves.
    try {
        return headWorkflowRuns(repoInfo, headSha);
    } catch (e) {
        console.warn('  ⚠️  head-run probe failed: ' + (e.message || e));
        return null;
    }
}


function hasActiveHeadRun(runs) {
    // hasActiveDispatchedRun semantics, widened to every run on the head:
    // any queued/in-progress/waiting/pending run means the state is about
    // to move on its own (a fresh kicker stamps the contexts, a validation
    // dispatch re-runs them) — rerunning cancelled runs under it would
    // only stack. Takes the pre-fetched head rollup (the action fetches
    // once and shares it with the target mapping — #695 review); a null
    // (failed probe) reads as no active run — fail OPEN. The ACTIVE
    // vocabulary comes from js/common/validationLiveness.js (gh-821 round-2
    // review: one constant, not parallel inline lists that drift).
    return (runs || []).some(function (r) {
        return validationLivenessModule.ACTIVE_RUN_STATES.indexOf(r.status) !== -1;
    });
}

// gh-798 (live fa PR #1420 rework leg, run 37828431528): the in-flight-leg
// exclusion for update_branch. A rework/review ai-teammate leg dispatched
// with workflowRef={branch} lands ON the PR head (its run head_sha IS the
// PR head), so an ACTIVE run of the leg workflow in the head rollup means
// the head is owned mid-run — the leg's timer pushes WIP auto-saves to that
// ref, and a silent refresh merged under it rejects the leg's next push
// non-fast-forward ("timer: git push failed" surfaced to the running
// agent). Same invariant as the ai_validating exclusion: a head with a leg
// in flight must not move. hasActiveHeadRun semantics (any
// queued/in_progress/waiting/pending run), NARROWED to the leg workflow
// path so unrelated CI on the head never blocks freshness, plus the same
// stale-zombie window the dispatch guard applies (a leg stuck 'queued' for
// hours ages out). Takes the pre-fetched head rollup (headWorkflowRunsSafe —
// the probe itself fails CLOSED in update_branch, unlike the rerun rule's
// fail-open read: one deferred refresh costs a tick, racing a live leg
// costs the leg's whole push stream).
function hasActiveLegRun(runs, workflowFile) {
    var suffix = '/' + String(workflowFile || 'ai-teammate.yml');
    return (runs || []).some(function (r) {
        if (!r) return false;
        var status = r.status;
        if (status !== 'queued' && status !== 'in_progress' &&
            status !== 'waiting' && status !== 'pending') return false;
        if (status !== 'in_progress' && isStaleNonRunningWorkflowRun(r, status)) return false;
        var p = String(r.path || '');
        return p.length >= suffix.length &&
            p.slice(p.length - suffix.length) === suffix;
    });
}

// gh-748 dispatch-race probe over the FULL head rollup (all workflows, all
// events, all triggering actors): a run that is ACTIVE now, or completed
// within graceMs, means somebody may have just ordered/produced CI on this
// head — the SM must not stack a second dispatch on it. A run completed
// seconds ago is exactly the registration-lag shape: its own CI child (a
// kicker's workflow_dispatch) can still be invisible to the event-filtered
// hasActiveDispatchedRun probe. Takes the pre-fetched head rollup
// (headWorkflowRunsSafe — a null failed probe reads as no race — fail
// OPEN, matching hasActiveDispatchedRun's error contract). A completed run
// with no parseable timestamp never blocks (cannot be aged — the 15-min
// completed grace of the dispatched probe covers it if it is CI).

